/// <summary>
/// Sets reservation.
/// </summary>
public void setReservation()
{
    next setReservation();

    /*Bug 191277 - CB515 - Events - Export orders reserving on order creation - start
     Sets reservation to 'None' for special orders (Export/Turn in/Forward).
    */
    if (salesTable.METSalesOrderType)
    {
        METSalesOrderTypes salesOrderTypes = salesTable.METSalesOrderTypes();

        if (salesOrderTypes.IncSpecialOrders)
        {
            salesLine.Reservation = ItemReservation::None;
        }

    }
    /*Bug 191277 - CB515 - Events - Export orders reserving on order creation - end*/
}
